CREATE OR REPLACE FUNCTION public.transfer_team_assignments(p_from_user_id uuid,p_to_user_id uuid,p_transfer_leads boolean DEFAULT true,p_transfer_properties boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare v_org uuid:=public.current_organization_id(); v_leads integer:=0; v_properties integer:=0; v_source_exists boolean:=false; v_destination_active boolean:=false; begin if v_org is null or not public.has_permission('team.manage') then raise exception 'Você não tem permissão para transferir carteiras.'; end if; if p_from_user_id is null or p_to_user_id is null then raise exception 'Informe o usuário de origem e o usuário de destino.'; end if; if p_from_user_id=p_to_user_id then raise exception 'O usuário de origem e o usuário de destino devem ser diferentes.'; end if; select exists(select 1 from public.organization_members where organization_id=v_org and user_id=p_from_user_id) into v_source_exists; select exists(select 1 from public.organization_members where organization_id=v_org and user_id=p_to_user_id and status='active') into v_destination_active; if not v_source_exists then raise exception 'O usuário de origem não pertence a esta empresa.'; end if; if not v_destination_active then raise exception 'O usuário de destino precisa estar ativo nesta empresa.'; end if; if coalesce(p_transfer_leads,false) then update public.leads set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_leads=row_count; end if; if coalesce(p_transfer_properties,false) then update public.properties set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_properties=row_count; end if; return jsonb_build_object('ok',true,'from_user_id',p_from_user_id,'to_user_id',p_to_user_id,'leads_transferred',v_leads,'properties_transferred',v_properties); end; $function$;

CREATE OR REPLACE FUNCTION public.transfer_team_workload(p_from_user uuid,p_to_user uuid,p_types text[] DEFAULT ARRAY['leads'::text,'properties'::text])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare v_org uuid; v_target_active boolean; v_source_member boolean; v_allowed text[]:=array['leads','properties','appointments','owner_captures','proposals','deals']; v_type text; v_count integer; v_counts jsonb:='{}'::jsonb; begin if auth.uid() is null then raise exception 'Sessão não informada.'; end if; if not public.has_permission('team.manage') then raise exception 'Você não tem permissão para transferir carteiras.'; end if; v_org:=public.current_organization_id(); if v_org is null then raise exception 'Organização não encontrada.'; end if; if p_from_user is null or p_to_user is null then raise exception 'Informe o usuário de origem e o usuário de destino.'; end if; if p_from_user=p_to_user then raise exception 'Origem e destino precisam ser usuários diferentes.'; end if; select exists(select 1 from public.organization_members where organization_id=v_org and user_id=p_from_user) into v_source_member; if not v_source_member then raise exception 'O usuário de origem não pertence a esta empresa.'; end if; select exists(select 1 from public.organization_members where organization_id=v_org and user_id=p_to_user and status='active') into v_target_active; if not v_target_active then raise exception 'O usuário de destino precisa estar ativo nesta empresa.'; end if; if p_types is null or cardinality(p_types)=0 then raise exception 'Selecione pelo menos um tipo de registro.'; end if; foreach v_type in array p_types loop if not(v_type=any(v_allowed)) then raise exception 'Tipo de registro não permitido: %',v_type; end if; execute format('update public.%I set assigned_to = $1 where assigned_to = $2',v_type) using p_to_user,p_from_user; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object(v_type,v_count); end loop; return jsonb_build_object('ok',true,'from_user_id',p_from_user,'to_user_id',p_to_user,'counts',v_counts,'transferred_at',now(),'transferred_by',auth.uid()); end; $function$;

CREATE OR REPLACE FUNCTION public.transfer_team_portfolio(p_from_user uuid,p_to_user uuid,p_scope text DEFAULT 'all'::text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare org_id uuid; source_ok boolean; target_ok boolean; c_leads integer:=0; c_appointments integer:=0; c_proposals integer:=0; c_deals integer:=0; c_properties integer:=0; c_captures integer:=0; begin if not public.has_permission('team.manage') then raise exception 'Você não tem permissão para transferir carteiras.'; end if; if p_from_user is null or p_to_user is null or p_from_user=p_to_user then raise exception 'Selecione dois usuários diferentes.'; end if; if p_scope not in('clients','properties','all') then raise exception 'Escopo de transferência inválido.'; end if; org_id:=public.current_organization_id(); if org_id is null then raise exception 'Empresa atual não encontrada.'; end if; select exists(select 1 from public.organization_members where organization_id=org_id and user_id=p_from_user and status in('active','disabled','invited')) into source_ok; select exists(select 1 from public.organization_members where organization_id=org_id and user_id=p_to_user and status='active') into target_ok; if not source_ok then raise exception 'Usuário de origem não pertence à equipe.'; end if; if not target_ok then raise exception 'O novo responsável precisa estar ativo na equipe.'; end if; if p_scope in('clients','all') then update public.leads set assigned_to=p_to_user where assigned_to=p_from_user; get diagnostics c_leads=row_count; update public.appointments set assigned_to=p_to_user where assigned_to=p_from_user; get diagnostics c_appointments=row_count; update public.proposals set assigned_to=p_to_user where assigned_to=p_from_user; get diagnostics c_proposals=row_count; update public.deals set assigned_to=p_to_user where assigned_to=p_from_user; get diagnostics c_deals=row_count; end if; if p_scope in('properties','all') then update public.properties set assigned_to=p_to_user where assigned_to=p_from_user; get diagnostics c_properties=row_count; update public.owner_captures set assigned_to=p_to_user where assigned_to=p_from_user; get diagnostics c_captures=row_count; end if; return jsonb_build_object('leads',c_leads,'appointments',c_appointments,'proposals',c_proposals,'deals',c_deals,'properties',c_properties,'captures',c_captures,'total',c_leads+c_appointments+c_proposals+c_deals+c_properties+c_captures); end; $function$;

CREATE OR REPLACE FUNCTION public.transfer_team_portfolio(p_from_user_id uuid,p_to_user_id uuid,p_tables text[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare org_id uuid; item text; moved integer; result jsonb:='{}'::jsonb; allowed_tables constant text[]:=array['leads','properties','appointments','owner_captures','proposals','deals']; begin if not public.has_permission('team.manage') then raise exception 'Sem permissão para transferir a carteira da equipe.'; end if; if p_from_user_id is null or p_to_user_id is null then raise exception 'Informe o usuário de origem e o novo responsável.'; end if; if p_from_user_id=p_to_user_id then raise exception 'O usuário de origem e o destino precisam ser diferentes.'; end if; if p_tables is null or cardinality(p_tables)=0 then raise exception 'Selecione pelo menos um tipo de registro.'; end if; org_id:=public.current_organization_id(); if org_id is null then raise exception 'Organização não encontrada.'; end if; if not exists(select 1 from public.organization_members m where m.organization_id=org_id and m.user_id=p_from_user_id) then raise exception 'O usuário de origem não pertence à sua empresa.'; end if; if not exists(select 1 from public.organization_members m where m.organization_id=org_id and m.user_id=p_to_user_id and m.status='active') then raise exception 'O novo responsável precisa ser um usuário ativo da sua empresa.'; end if; foreach item in array p_tables loop if not(item=any(allowed_tables)) then raise exception 'Tipo de registro inválido: %',item; end if; moved:=0; execute format('update public.%I set assigned_to = $1 where assigned_to = $2',item) using p_to_user_id,p_from_user_id; get diagnostics moved=row_count; result:=result||jsonb_build_object(item,moved); end loop; return result; end; $function$;

CREATE OR REPLACE FUNCTION public.transfer_team_portfolio(p_from_user_id uuid,p_to_user_id uuid,p_transfer_clients boolean DEFAULT true,p_transfer_properties boolean DEFAULT true,p_transfer_related boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare v_org uuid; v_count integer; v_leads integer:=0; v_properties integer:=0; v_related integer:=0; begin if not public.has_permission('team.manage') then raise exception 'Sem permissão para transferir carteira'; end if; if p_from_user_id is null or p_to_user_id is null or p_from_user_id=p_to_user_id then raise exception 'Usuários de origem e destino inválidos'; end if; v_org:=public.current_organization_id(); if v_org is null then raise exception 'Empresa não encontrada'; end if; if not exists(select 1 from public.organization_members where organization_id=v_org and user_id=p_from_user_id and status<>'disabled') then raise exception 'Usuário de origem não pertence à empresa'; end if; if not exists(select 1 from public.organization_members where organization_id=v_org and user_id=p_to_user_id and status='active') then raise exception 'Novo responsável não está ativo na empresa'; end if; if p_transfer_clients then update public.leads set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_leads=row_count; end if; if p_transfer_properties then update public.properties set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_properties=row_count; end if; if p_transfer_related then update public.appointments set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_count=row_count; v_related:=v_related+v_count; update public.owner_captures set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_count=row_count; v_related:=v_related+v_count; update public.proposals set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_count=row_count; v_related:=v_related+v_count; update public.deals set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_count=row_count; v_related:=v_related+v_count; end if; return jsonb_build_object('leads',v_leads,'properties',v_properties,'related',v_related); end; $function$;

CREATE OR REPLACE FUNCTION public.transfer_team_portfolio(p_from_user_id uuid,p_to_user_id uuid,p_transfer_leads boolean DEFAULT true,p_transfer_properties boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare v_org uuid; v_leads integer:=0; v_properties integer:=0; v_appointments integer:=0; v_proposals integer:=0; v_deals integer:=0; v_captures integer:=0; begin v_org:=public.current_organization_id(); if v_org is null then raise exception 'Usuário sem organização ativa.'; end if; if not public.has_permission('team.manage') then raise exception 'Sem permissão para transferir carteiras.'; end if; if p_from_user_id is null or p_to_user_id is null then raise exception 'Informe o usuário de origem e o usuário de destino.'; end if; if p_from_user_id=p_to_user_id then raise exception 'O usuário de destino deve ser diferente do usuário de origem.'; end if; if not coalesce(p_transfer_leads,false) and not coalesce(p_transfer_properties,false) then raise exception 'Selecione clientes, imóveis ou ambos para transferir.'; end if; if not exists(select 1 from public.organization_members m where m.organization_id=v_org and m.user_id=p_from_user_id) then raise exception 'O usuário de origem não pertence à sua empresa.'; end if; if not exists(select 1 from public.organization_members m where m.organization_id=v_org and m.user_id=p_to_user_id and m.status='active') then raise exception 'O usuário de destino precisa estar ativo na sua empresa.'; end if; if coalesce(p_transfer_leads,false) then update public.appointments a set assigned_to=p_to_user_id where a.assigned_to=p_from_user_id and exists(select 1 from public.leads l where l.id=a.lead_id and l.assigned_to=p_from_user_id); get diagnostics v_appointments=row_count; update public.proposals p set assigned_to=p_to_user_id where p.assigned_to=p_from_user_id and exists(select 1 from public.leads l where l.id=p.lead_id and l.assigned_to=p_from_user_id); get diagnostics v_proposals=row_count; update public.deals d set assigned_to=p_to_user_id where d.assigned_to=p_from_user_id and exists(select 1 from public.leads l where l.id=d.lead_id and l.assigned_to=p_from_user_id); get diagnostics v_deals=row_count; update public.leads set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_leads=row_count; end if; if coalesce(p_transfer_properties,false) then update public.owner_captures c set assigned_to=p_to_user_id where c.assigned_to=p_from_user_id and c.converted_property_id is not null and exists(select 1 from public.properties p where p.id=c.converted_property_id and p.assigned_to=p_from_user_id); get diagnostics v_captures=row_count; update public.properties set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_properties=row_count; end if; return jsonb_build_object('leads',v_leads,'properties',v_properties,'appointments',v_appointments,'proposals',v_proposals,'deals',v_deals,'captures',v_captures); end; $function$;

CREATE OR REPLACE FUNCTION public.transfer_team_portfolio(p_from_user_id uuid,p_to_user_id uuid,p_transfer_leads boolean DEFAULT true,p_transfer_properties boolean DEFAULT true,p_transfer_appointments boolean DEFAULT true,p_transfer_captures boolean DEFAULT true,p_transfer_proposals boolean DEFAULT true,p_transfer_deals boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ declare v_org uuid; v_role text; v_from_member public.organization_members%rowtype; v_to_member public.organization_members%rowtype; v_leads integer:=0; v_properties integer:=0; v_appointments integer:=0; v_captures integer:=0; v_proposals integer:=0; v_deals integer:=0; begin v_org:=public.current_organization_id(); v_role:=public.current_team_role(); if v_org is null then raise exception 'Empresa não encontrada para o usuário atual.'; end if; if v_role not in('owner','admin') then raise exception 'Somente Proprietário ou Administrador pode transferir carteiras.'; end if; if p_from_user_id is null or p_to_user_id is null then raise exception 'Informe o usuário de origem e o usuário de destino.'; end if; if p_from_user_id=p_to_user_id then raise exception 'Origem e destino precisam ser usuários diferentes.'; end if; select * into v_from_member from public.organization_members where organization_id=v_org and user_id=p_from_user_id limit 1; if not found then raise exception 'O usuário de origem não pertence a esta empresa.'; end if; select * into v_to_member from public.organization_members where organization_id=v_org and user_id=p_to_user_id limit 1; if not found then raise exception 'O usuário de destino não pertence a esta empresa.'; end if; if v_to_member.status<>'active' then raise exception 'O usuário de destino precisa estar ativo.'; end if; if not(p_transfer_leads or p_transfer_properties or p_transfer_appointments or p_transfer_captures or p_transfer_proposals or p_transfer_deals) then raise exception 'Selecione pelo menos um tipo de carteira para transferir.'; end if; if p_transfer_leads then update public.leads set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_leads=row_count; end if; if p_transfer_properties then update public.properties set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_properties=row_count; end if; if p_transfer_appointments then update public.appointments set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_appointments=row_count; end if; if p_transfer_captures then update public.owner_captures set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_captures=row_count; end if; if p_transfer_proposals then update public.proposals set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_proposals=row_count; end if; if p_transfer_deals then update public.deals set assigned_to=p_to_user_id where assigned_to=p_from_user_id; get diagnostics v_deals=row_count; end if; return jsonb_build_object('leads',v_leads,'properties',v_properties,'appointments',v_appointments,'captures',v_captures,'proposals',v_proposals,'deals',v_deals,'total',v_leads+v_properties+v_appointments+v_captures+v_proposals+v_deals); end; $function$;;
